-- Read-only Production inventory, 2026-10-15. No learner tables read.
-- Potential content eligibility at some manifest-allowed unit, before learner exclusions.
with latest as(select distinct on(content_item_id) id,content_item_id,status from app.content_item_versions order by content_item_id,version_num desc),labels as(select distinct on(content_item_id) * from app.content_taxonomy_labels where label_scope='serving' and label_status='validated' and superseded_by is null order by content_item_id,label_version desc),q as(select v.id,ci.id item_id,ci.content_key,ci.item_type,ci.frq_form,ci.exam_pack_version_id,s.subject_key,cell.topic_code,l.content_item_id label_id,l.required_units,l.max_required_unit,(lv.id=v.id and lv.status='published') latest_published, l.validated_against_taxo_hash=app.taxonomy_relevant_hash(v.id) fresh_label,app.content_item_is_teaching(ci.id) teaching, exists(select 1 from app.home_release_manifest m where m.exam_pack_version_id=ci.exam_pack_version_id and l.max_required_unit<=any(m.allowed_unit_numbers)) manifest_reachable from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.exam_pack_versions epv on epv.id=ci.exam_pack_version_id join app.exam_packs ep on ep.id=epv.exam_pack_id join app.subjects s on s.id=ep.subject_id left join latest lv on lv.content_item_id=ci.id left join labels l on l.content_item_id=ci.id left join lateral(select cc.topic_code from app.content_item_cells cc where cc.content_item_version_id=v.id and cc.superseded_by is null order by cc.is_primary desc nulls last,cc.created_at limit 1)cell on true where ci.status='published' and v.status='published' and s.subject_key in('ap-calculus-ab','ap-calculus-bc','ap-chemistry')), checked as(select *,coalesce(latest_published and fresh_label and manifest_reachable and not teaching and (item_type in('mcq','quantitative') or(item_type='frq' and frq_form in('short','long'))),false) practice_eligible from q) select subject_key,count(*) filter(where topic_code is null) missing_topic,count(*) filter(where topic_code is null and practice_eligible) practice_eligible_missing_topic,count(*) filter(where topic_code is null and label_id is not null) with_validated_serving_label,count(*) filter(where topic_code is null and fresh_label) fresh_label,count(*) filter(where topic_code is null and manifest_reachable) reachable_unit,count(*) filter(where topic_code is null and teaching) teaching_missing_topic from checked group by subject_key order by subject_key;

-- Exact priority keys, grouped by earliest required unit and type.
with latest as(select distinct on(content_item_id) id,content_item_id,status from app.content_item_versions order by content_item_id,version_num desc),labels as(select distinct on(content_item_id) * from app.content_taxonomy_labels where label_scope='serving' and label_status='validated' and superseded_by is null order by content_item_id,label_version desc),q as(select v.id,ci.id item_id,ci.content_key,ci.item_type,ci.frq_form,ci.exam_pack_version_id,s.subject_key,cell.topic_code,l.content_item_id label_id,l.required_units,l.max_required_unit,(lv.id=v.id and lv.status='published') latest_published, l.validated_against_taxo_hash=app.taxonomy_relevant_hash(v.id) fresh_label,app.content_item_is_teaching(ci.id) teaching, exists(select 1 from app.home_release_manifest m where m.exam_pack_version_id=ci.exam_pack_version_id and l.max_required_unit<=any(m.allowed_unit_numbers)) manifest_reachable from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.exam_pack_versions epv on epv.id=ci.exam_pack_version_id join app.exam_packs ep on ep.id=epv.exam_pack_id join app.subjects s on s.id=ep.subject_id left join latest lv on lv.content_item_id=ci.id left join labels l on l.content_item_id=ci.id left join lateral(select cc.topic_code from app.content_item_cells cc where cc.content_item_version_id=v.id and cc.superseded_by is null order by cc.is_primary desc nulls last,cc.created_at limit 1)cell on true where ci.status='published' and v.status='published' and s.subject_key in('ap-calculus-ab','ap-calculus-bc','ap-chemistry')), checked as(select *,coalesce(latest_published and fresh_label and manifest_reachable and not teaching and (item_type in('mcq','quantitative') or(item_type='frq' and frq_form in('short','long'))),false) practice_eligible from q) select subject_key,max_required_unit,item_type,count(*) n,jsonb_agg(content_key order by content_key) content_keys from checked where topic_code is null and practice_eligible group by subject_key,max_required_unit,item_type order by subject_key,max_required_unit,item_type;

-- TASK-0076 authored source/provenance (no answer keys).
select ci.content_key,v.id version_id,v.stem,cc.topic_code,cc.assignment_status,cc.source,cc.is_primary from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id left join app.content_item_cells cc on cc.content_item_version_id=v.id and cc.superseded_by is null where ci.content_key in ('apchem-mcq-026','apchem-mcq-sv-026-v1','apchem-mcq-sv-026-v2','apchem-mcq-sv-026-v3','apchem-oht-2.5','apchem-frq-u13g-2-5','apchem-mcq-078','apchem-mcq-sv-078-v1') and ci.status='published' and v.status='published' order by ci.content_key,cc.is_primary desc;

-- TASK-0076 practice eligibility.
with latest as(select distinct on(content_item_id) id,content_item_id,status from app.content_item_versions order by content_item_id,version_num desc),labels as(select distinct on(content_item_id) * from app.content_taxonomy_labels where label_scope='serving' and label_status='validated' and superseded_by is null order by content_item_id,label_version desc),q as(select v.id,ci.id item_id,ci.content_key,ci.item_type,ci.frq_form,ci.exam_pack_version_id,s.subject_key,cell.topic_code,l.content_item_id label_id,l.required_units,l.max_required_unit,(lv.id=v.id and lv.status='published') latest_published, l.validated_against_taxo_hash=app.taxonomy_relevant_hash(v.id) fresh_label,app.content_item_is_teaching(ci.id) teaching, exists(select 1 from app.home_release_manifest m where m.exam_pack_version_id=ci.exam_pack_version_id and l.max_required_unit<=any(m.allowed_unit_numbers)) manifest_reachable from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.exam_pack_versions epv on epv.id=ci.exam_pack_version_id join app.exam_packs ep on ep.id=epv.exam_pack_id join app.subjects s on s.id=ep.subject_id left join latest lv on lv.content_item_id=ci.id left join labels l on l.content_item_id=ci.id left join lateral(select cc.topic_code from app.content_item_cells cc where cc.content_item_version_id=v.id and cc.superseded_by is null order by cc.is_primary desc nulls last,cc.created_at limit 1)cell on true where ci.status='published' and v.status='published' and s.subject_key in('ap-calculus-ab','ap-calculus-bc','ap-chemistry')), checked as(select *,coalesce(latest_published and fresh_label and manifest_reachable and not teaching and (item_type in('mcq','quantitative') or(item_type='frq' and frq_form in('short','long'))),false) practice_eligible from q) select content_key,subject_key,practice_eligible,label_id is not null active_validated_label,fresh_label,manifest_reachable,latest_published,teaching from checked where content_key in('apchem-mcq-026','apchem-mcq-sv-026-v1','apchem-mcq-sv-026-v2','apchem-mcq-sv-026-v3','apchem-oht-2.5','apchem-frq-u13g-2-5','apchem-mcq-078','apchem-mcq-sv-078-v1') order by content_key;

